import time
import math


class KVCache:
    def __init__(self, capacity, ttl_seconds, clock=None):
        if isinstance(capacity, bool) or not isinstance(capacity, int):
            raise ValueError("capacity must be a non-bool integer >= 0")
        if capacity < 0:
            raise ValueError("capacity must be a non-bool integer >= 0")
        if isinstance(ttl_seconds, bool) or not isinstance(ttl_seconds, (int, float)):
            raise ValueError("ttl_seconds must be a finite non-bool int/float >= 0")
        if not math.isfinite(ttl_seconds):
            raise ValueError("ttl_seconds must be a finite non-bool int/float >= 0")
        if ttl_seconds < 0:
            raise ValueError("ttl_seconds must be a finite non-bool int/float >= 0")
        self._capacity = capacity
        self._ttl = ttl_seconds
        self._clock = clock if clock is not None else time.monotonic
        self._data = {}   # key -> [value, expiry]
        self._order = {}  # key -> key; insertion order = LRU order (oldest first)

    def _now(self):
        return self._clock()

    def _purge_expired(self, now):
        expired = [k for k, (v, exp) in self._data.items() if now >= exp]
        for k in expired:
            del self._data[k]
            self._order.pop(k, None)

    def _touch(self, key):
        if key in self._order:
            del self._order[key]
        self._order[key] = key

    def get(self, key):
        entry = self._data.get(key)
        if entry is None:
            return None
        value, expiry = entry
        if self._now() >= expiry:
            del self._data[key]
            self._order.pop(key, None)
            return None
        self._touch(key)
        return value

    def put(self, key, value):
        now = self._now()
        # Remove existing entry first so updating this key never evicts another live entry.
        if key in self._data:
            del self._data[key]
            self._order.pop(key, None)
        # Before evicting a live LRU entry, remove ALL expired entries (including recently accessed).
        self._purge_expired(now)
        if self._capacity == 0 or self._ttl == 0:
            return
        while len(self._data) >= self._capacity:
            lru_key = next(iter(self._order))
            del self._order[lru_key]
            del self._data[lru_key]
        self._data[key] = [value, now + self._ttl]
        self._order[key] = key

    def delete(self, key):
        entry = self._data.pop(key, None)
        if entry is None:
            return False
        value, expiry = entry
        self._order.pop(key, None)
        if self._now() >= expiry:
            return False
        return True
